function devePesquisarNaWeb(texto) {
  if (!texto) return false;
  let t = texto.trim().toLowerCase();
  t = t.replace(/[!?,;.]+/g, ' ').replace(/\s+/g, ' ').trim();
  const tokensCasuais = new Set([
    'ok', 'tudo', 'bem', 'bom', 'td', 'certo', 'cima', 'beleza', 'blz', 'tranquilo', 
    'como', 'vai', 'voce', 'você', 'esta', 'está', 'e', 'ai', 'aí', 'opa', 'oi', 
    'ola', 'olá', 'bom', 'dia', 'boa', 'tarde', 'noite', 'valeu', 'obrigado', 
    'obrigada', 'combinado', 'fechado', 'sim', 'ta', 'tá', 'show', 'top', 'tmj', 
    'marcao', 'marcão', 'fala', 'irmão', 'irmao', 'parceiro', 'campeão', 'campeao'
  ]);
  const palavras = t.split(' ').filter(w => w.length > 0);
  if (palavras.length > 0 && palavras.every(w => tokensCasuais.has(w))) return false;
  if (/^(treinei|treino pago|t[aá] pago|fui treinar|acabei o treino|hoje tem|cansei|pesando|estou com|tenho \d+|concordo|fechado)/i.test(t)) {
    return false;
  }
  const temInterrogacao = texto.includes('?');
  const termosPergunta = /\b(o que|oq|qual|quais|como|por que|pq|quanto|quantos|quem|onde|quando|pesquisa|pesquise|busca|busque|explica|explique|sabe me dizer|me tira uma d[uú]vida|d[uú]vida|voc[eê] conhece|voce conhece|indica|recomenda|vale a pena|funciona|estudo|pesquisa recente)\b/i.test(t);
  return termosPergunta || (temInterrogacao && palavras.length >= 3);
}

