  let aVal = parseFloat(mAlt[1].replace(',', '.'));
  if (aVal < 3.0) aVal = Math.round(aVal * 100);
  if (aVal >= 120 && aVal <= 230) alturaDetectada = aVal;
}

let idadeDetectada = null;
const mIdade = userMsgLower.match(/\b(\d{1,2})\s*anos\b/i);
if (mIdade) {
  const idVal = parseInt(mIdade[1], 10);
  if (idVal >= 12 && idVal <= 100) idadeDetectada = idVal;
}

let localDetectado = null;
if (userMsgLower.includes('em casa') || userMsgLower.includes('na casa') || userMsgLower.includes('treino em casa') || userMsgLower.includes('casa')) {
  localDetectado = 'casa';
} else if (userMsgLower.includes('academia') || userMsgLower.includes('musculação') || userMsgLower.includes('aparelho')) {
