}

let restricoesDetectadas = null;
if (userMsgLower.includes('joelho') || userMsgLower.includes('coluna') || userMsgLower.includes('lombar') || userMsgLower.includes('ombro') || userMsgLower.includes('hérnia') || userMsgLower.includes('hernia') || userMsgLower.includes('menisco')) {
