  if (userMsgLower.includes('hérnia') || userMsgLower.includes('hernia')) dores.push('hérnia de disco');
  restricoesDetectadas = dores.join(', ');
} else if (userMsgLower.includes('nenhuma') || userMsgLower.includes('sem dor') || userMsgLower.includes('tudo certo') || userMsgLower.includes('tudo ok')) {
  restricoesDetectadas = 'Nenhuma dor ou lesão reportada';
}

if (concordouLgpd || pesoDetectado || alturaDetectada || idadeDetectada || localDetectado || restricoesDetectadas) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://admin.marcaopersonal.com/api/vip/salvar-anamnese',
      body: {
        telefone: info.number,
        remote_jid: info.remoteJid,
        nome: info.pushName || info.nomeValido || (info.isEvandro ? 'Evandro Gallina' : 'Aluno'),
        peso: pesoDetectado,
        altura_cm: alturaDetectada,
        idade: idadeDetectada,
        local_treino: localDetectado,
