    });
  } catch(e) {}
}

// Se o Chefe confirmou LGPD explicitamente, garante resposta comemorativa caso o LLM não tenha respondido
if (info.isEvandro && concordouLgpd && (!rawContent || rawContent.length < 15)) {
  textoLimpo = "Termo LGPD e responsabilidade confirmados com sucesso, meu chefe! Ficha 100% liberada! Bora montar seu protocolo e sua dieta de alta performance! Me diz o que você quer priorizar hoje! 💪🦁";
}

